actions.apply:
$sig = '[DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)] public static extern bool MoveFileEx(string lpExistingFileName, string lpNewFileName, int dwFlags);'
Add-Type -Namespace VxThumb -Name Native -MemberDefinition $sig -ErrorAction Stop
$dir = Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Explorer'
$now = 0; $later = 0; $failed = 0
foreach ($f in @(Get-ChildItem -LiteralPath $dir -Filter 'thumbcache_*.db' -Force -File -ErrorAction SilentlyContinue)) {
    try { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop; $now++ }
    catch {
        # in use by Explorer: MOVEFILE_DELAY_UNTIL_REBOOT (4) deletes it at the next start, before Explorer runs
        if ([VxThumb.Native]::MoveFileEx($f.FullName, $null, 4)) { $later++ } else { $failed++ }
    }
}
$oe = [string][char]0x00F6; $ae = [string][char]0x00E4
Write-Output ([string]$now + ' Vorschaubild-Datei(en) gel' + $oe + 'scht, ' + [string]$later + ' werden beim n' + $ae + 'chsten Neustart gel' + $oe + 'scht.')
if ($failed -gt 0) { throw ([string]$failed + ' Datei(en) konnten nicht entfernt werden.') }
